function _diff3d_respawn_lowopt_tests()
    project = Base.active_project()
    cmd = String[Base.julia_cmd().exec...]
    append!(cmd, ["--startup-file=no", "-O0", "--compile=min"])
    project !== nothing && push!(cmd, "--project=$(dirname(project))")
    push!(cmd, "--eval")
    push!(cmd, """
        empty!(LOAD_PATH)
        append!(LOAD_PATH, $(repr(String.(LOAD_PATH))))
        empty!(Base.DEPOT_PATH)
        append!(Base.DEPOT_PATH, $(repr(String.(Base.DEPOT_PATH))))
        cd($(repr(pwd())))
        include($(repr(@__FILE__)))
    """)
    withenv("DIFF3D_TEST_LOWOPT" => "1") do
        exit(success(Cmd(cmd)) ? 0 : 1)
    end
end

# Julia/LLVM can spend minutes optimizing this large monolithic test file under
# the default `Pkg.test()` settings. Run the exact same file in a low-compile
# child process so `Pkg.test()` reaches the assertions instead of timing out in
# compiler optimization.
if get(ENV, "DIFF3D_TEST_LOWOPT", "") != "1" && Base.JLOptions().opt_level > 0
    _diff3d_respawn_lowopt_tests()
end

# The package-test suite respawns under `-O0 --compile=min` to keep compile time
# bounded in CI. Allocation budgets are only meaningful in optimized code, so
# enforce them only when Julia is running with optimizer passes enabled.
const DIFF3D_ALLOC_ASSERTIONS_ENABLED = Base.JLOptions().opt_level > 0

function _diff3d_start_ci_test_heartbeat()
    get(ENV, "CI", "") == "true" || return nothing
    return @async while true
        sleep(60)
        println(stderr, "DIFF3D_TEST_HEARTBEAT ", round(Int, time()))
        flush(stderr)
    end
end

const DIFF3D_CI_TEST_HEARTBEAT = _diff3d_start_ci_test_heartbeat()

macro test_opt_alloc(limit, expr)
    quote
        @test !DIFF3D_ALLOC_ASSERTIONS_ENABLED ||
              (@allocated($(esc(expr))) <= $(esc(limit)))
    end
end

using Test
using Base64
using Diff3D
using ForwardDiff
using TOML

deterministic_array(dims::Int...) =
    reshape([mod(37 * i + 11, 101) / 100 for i in 1:prod(dims)], dims)

deterministic_bytes(n::Int) =
    UInt8[mod(53 * i + 19, 256) for i in 1:n]

struct TestDirectionalLikeLight <: AbstractLight
    color::Color3{Float64}
    intensity::Float64
    direction::Vec3{Float64}
end

Diff3D.light_contribution(light::TestDirectionalLikeLight, position::Vec3) =
    (light.color, light.intensity, light.direction)

const TEST_ADAM7_PASSES = (
    (0, 0, 8, 8),
    (4, 0, 8, 8),
    (0, 4, 4, 8),
    (2, 0, 4, 4),
    (0, 2, 2, 4),
    (1, 0, 2, 2),
    (0, 1, 1, 2),
)

test_be32(x::Integer) =
    UInt8[(x >> 24) & 0xff, (x >> 16) & 0xff, (x >> 8) & 0xff, x & 0xff]

test_pass_size(n::Int, start::Int, step::Int) =
    n <= start ? 0 : ((n - start + step - 1) ÷ step)

function test_paeth(a::Int, b::Int, c::Int)
    p = a + b - c
    pa = abs(p - a)
    pb = abs(p - b)
    pc = abs(p - c)
    return pa <= pb && pa <= pc ? a : (pb <= pc ? b : c)
end

function test_png_filter(scanline::Vector{UInt8}, prev::Vector{UInt8},
                         bpp::Int, ftype::UInt8)
    out = similar(scanline)
    for i in eachindex(scanline)
        a = i > bpp ? scanline[i-bpp] : 0x00
        b = prev[i]
        c = i > bpp ? prev[i-bpp] : 0x00
        pred = if ftype == 0
            0
        elseif ftype == 1
            Int(a)
        elseif ftype == 2
            Int(b)
        elseif ftype == 3
            (Int(a) + Int(b)) ÷ 2
        elseif ftype == 4
            test_paeth(Int(a), Int(b), Int(c))
        else
            error("bad test PNG filter")
        end
        out[i] = UInt8(mod(Int(scanline[i]) - pred, 256))
    end
    return out
end

function test_adam7_png_bytes(img::Array{T,3}) where {T<:Unsigned}
    H, W, C = size(img)
    C in (1, 2, 3, 4) ||
        error("test_adam7_png_bytes expects gray, gray+alpha, RGB, or RGBA data")
    bitdepth = T === UInt8 ? 8 : T === UInt16 ? 16 :
               error("test_adam7_png_bytes expects UInt8 or UInt16 data")
    color_type = C == 1 ? 0x00 : C == 2 ? 0x04 : C == 3 ? 0x02 : 0x06
    raw = UInt8[]
    bps = bitdepth ÷ 8
    bpp = C * bps
    for (pass_index, (x0, y0, xstep, ystep)) in enumerate(TEST_ADAM7_PASSES)
        pass_w = test_pass_size(W, x0, xstep)
        pass_h = test_pass_size(H, y0, ystep)
        (pass_w == 0 || pass_h == 0) && continue
        prev = zeros(UInt8, pass_w * bpp)
        for prow in 0:(pass_h - 1)
            scanline = Vector{UInt8}(undef, pass_w * bpp)
            k = 1
            row = y0 + prow * ystep + 1
            for pcol in 0:(pass_w - 1)
                col = x0 + pcol * xstep + 1
                for c in 1:C
                    value = UInt(img[row, col, c])
                    if bitdepth == 8
                        scanline[k] = UInt8(value)
                        k += 1
                    else
                        scanline[k] = UInt8((value >> 8) & 0xff)
                        scanline[k + 1] = UInt8(value & 0xff)
                        k += 2
                    end
                end
            end
            ftype = UInt8((pass_index + prow - 1) % 5)
            push!(raw, ftype)
            append!(raw, test_png_filter(scanline, prev, bpp, ftype))
            prev = scanline
        end
    end
    io = IOBuffer()
    write(io, UInt8[137, 80, 78, 71, 13, 10, 26, 10])
    ihdr = UInt8[]
    append!(ihdr, test_be32(W))
    append!(ihdr, test_be32(H))
    append!(ihdr, UInt8[bitdepth, color_type, 0x00, 0x00, 0x01])
    Diff3D._png_chunk(io, "IHDR", ihdr)
    Diff3D._png_chunk(io, "IDAT", Diff3D._zlib_store(raw))
    Diff3D._png_chunk(io, "IEND", UInt8[])
    return take!(io)
end

function test_pack_png_indices(indices::Vector{UInt8}, bitdepth::Int)
    bitdepth in (1, 2, 4, 8) || error("test palette PNG bit depth must be 1, 2, 4, or 8")
    max_index = UInt8((UInt16(1) << bitdepth) - 1)
    out = zeros(UInt8, cld(length(indices) * bitdepth, 8))
    for (i, idx) in enumerate(indices)
        idx <= max_index || error("palette index exceeds bit depth")
        pcol = i - 1
        if bitdepth == 8
            out[i] = idx
        else
            bitpos = pcol * bitdepth
            byte_i = (bitpos ÷ 8) + 1
            shift = 8 - bitdepth - (bitpos % 8)
            out[byte_i] |= UInt8(idx << shift)
        end
    end
    return out
end

function test_palette_png_bytes(indices::Matrix{UInt8}; bitdepth::Int=8,
                                palette::Vector{UInt8}, trns::Vector{UInt8}=UInt8[],
                                interlace::Bool=false)
    H, W = size(indices)
    raw = UInt8[]
    if interlace
        for (pass_index, (x0, y0, xstep, ystep)) in enumerate(TEST_ADAM7_PASSES)
            pass_w = test_pass_size(W, x0, xstep)
            pass_h = test_pass_size(H, y0, ystep)
            (pass_w == 0 || pass_h == 0) && continue
            prev = zeros(UInt8, cld(pass_w * bitdepth, 8))
            for prow in 0:(pass_h - 1)
                row = y0 + prow * ystep + 1
                scanline = test_pack_png_indices(
                    UInt8[indices[row, x0 + pcol * xstep + 1] for pcol in 0:(pass_w - 1)],
                    bitdepth)
                ftype = UInt8((pass_index + prow - 1) % 5)
                push!(raw, ftype)
                append!(raw, test_png_filter(scanline, prev, 1, ftype))
                prev = scanline
            end
        end
    else
        prev = zeros(UInt8, cld(W * bitdepth, 8))
        for row in 1:H
            scanline = test_pack_png_indices(vec(indices[row, :]), bitdepth)
            ftype = UInt8((row - 1) % 5)
            push!(raw, ftype)
            append!(raw, test_png_filter(scanline, prev, 1, ftype))
            prev = scanline
        end
    end
    io = IOBuffer()
    write(io, UInt8[137, 80, 78, 71, 13, 10, 26, 10])
    ihdr = UInt8[]
    append!(ihdr, test_be32(W))
    append!(ihdr, test_be32(H))
    append!(ihdr, UInt8[bitdepth, 0x03, 0x00, 0x00, interlace ? 0x01 : 0x00])
    Diff3D._png_chunk(io, "IHDR", ihdr)
    Diff3D._png_chunk(io, "PLTE", palette)
    isempty(trns) || Diff3D._png_chunk(io, "tRNS", trns)
    Diff3D._png_chunk(io, "IDAT", Diff3D._zlib_store(raw))
    Diff3D._png_chunk(io, "IEND", UInt8[])
    return take!(io)
end

