                    "interpolation=:cubic",
                ],
                prerequisites=["quaternion keyframe tracks", "scale keyframe tracks"],
            ),
        )
        @test Set(keys(focused_checks)) == expected_ids
        for entry in examples
            @test startswith(entry["upstream_id"], "threejs_")
            @test startswith(entry["upstream_url"], "https://threejs.org/examples/#")
            @test entry["status"] in valid_status
            @test entry["prerequisites"] isa Vector
            @test entry["known_deviations"] isa Vector
            @test entry["verification"] isa Vector
            if entry["status"] != "planned"
                script = joinpath(@__DIR__, "..", entry["local_script"])
                @test isfile(script)
                output_stem = splitext(basename(entry["local_script"]))[1]
                smoke = "python examples/browser_webgl_smoke.py examples/output/$output_stem.html"
                @test smoke in entry["verification"]
                @test all(!occursin("<generated html>", cmd) for cmd in entry["verification"])
                if entry["status"] == "covered"
                    deviations = lowercase(join(entry["known_deviations"], " "))
                    @test !occursin("representative", deviations)
                    @test !occursin("rather than exact", deviations)
                end
                source = read(script, String)
                check = focused_checks[entry["upstream_id"]]
                for needle in check.source
                    @test occursin(needle, source)
                end
                for prerequisite in check.prerequisites
                    @test prerequisite in entry["prerequisites"]
                end
            end
        end
    end

    @testset "Vec3 arithmetic" begin
        a = Vec3(1.0, 2.0, 3.0)
        b = Vec3(4.0, 5.0, 6.0)
        c = a + b
        @test c.x ≈ 5.0
        @test c.y ≈ 7.0
        @test c.z ≈ 9.0

        d = a - b
        @test d.x ≈ -3.0

        s = a * 2.0
        @test s.x ≈ 2.0 && s.y ≈ 4.0 && s.z ≈ 6.0

        @test dot(a, b) ≈ 32.0  # 1*4 + 2*5 + 3*6

        cr = cross(Vec3(1,0,0), Vec3(0,1,0))
        @test cr.x ≈ 0.0 && cr.y ≈ 0.0 && cr.z ≈ 1.0

        @test norm(Vec3(3.0, 4.0, 0.0)) ≈ 5.0

        n = normalize(Vec3(0.0, 0.0, 5.0))
        @test n.z ≈ 1.0
        @test norm(n) ≈ 1.0
    end

    @testset "Color3" begin
        c1 = Color3(0.5, 0.3, 0.1)
        c2 = Color3(0.2, 0.4, 0.6)
        c3 = c1 + c2
        @test c3.r ≈ 0.7
        @test c3.g ≈ 0.7
        @test c3.b ≈ 0.7

        c4 = c1 * 2.0
        @test c4.r ≈ 1.0

        c5 = c1 * c2  # component-wise
        @test c5.r ≈ 0.1

        c_hex = Color3(UInt32(0xFF8000))
        @test c_hex.r ≈ 1.0
        @test c_hex.g ≈ 128/255 atol=1e-12
    end

    @testset "Light constructors" begin
        target = Vec3(1.0, 0.5, -2.0)
        light = SpotLight(position=Vec3(2.0, 3.0, 4.0), target=target)
        @test light.target == target
    end

    @testset "Mat4 identity and transform" begin
        I4 = Mat4()
        v = Vec4(1.0, 2.0, 3.0, 1.0)
        w = mat4_transform_vec4(I4, v)
        @test w.x ≈ 1.0 && w.y ≈ 2.0 && w.z ≈ 3.0 && w.w ≈ 1.0

        T = mat4_translation(10.0, 20.0, 30.0)
        p = mat4_transform_point(T, Vec3(1.0, 2.0, 3.0))
        @test p.x ≈ 11.0
        @test p.y ≈ 22.0
        @test p.z ≈ 33.0

        S = mat4_scaling(2.0, 3.0, 4.0)
        ps = mat4_transform_point(S, Vec3(1.0, 1.0, 1.0))
        @test ps.x ≈ 2.0 && ps.y ≈ 3.0 && ps.z ≈ 4.0
    end

    @testset "Mat4 rotation" begin
        # 90° rotation around Z: (1,0,0) → (0,1,0)
        Rz = mat4_rotation_z(π/2)
        p = mat4_transform_point(Rz, Vec3(1.0, 0.0, 0.0))
        @test p.x ≈ 0.0 atol=1e-12
        @test p.y ≈ 1.0 atol=1e-12
        @test p.z ≈ 0.0 atol=1e-12

        # 90° rotation around X: (0,1,0) → (0,0,1)
        Rx = mat4_rotation_x(π/2)
        p2 = mat4_transform_point(Rx, Vec3(0.0, 1.0, 0.0))
        @test p2.x ≈ 0.0 atol=1e-12
        @test p2.y ≈ 0.0 atol=1e-12
        @test p2.z ≈ 1.0 atol=1e-12
    end

    @testset "Mat4 inverse" begin
        T = mat4_translation(3.0, -7.0, 11.0)
        Tinv = mat4_inverse(T)
        prod = T * Tinv
        for i in 1:4
            for j in 1:4
                expected = i == j ? 1.0 : 0.0
                @test mat4_get(prod, i, j) ≈ expected atol=1e-10
            end
        end
    end

    @testset "Mat4 multiply — identical output, bounded allocation" begin
        T = mat4_translation(3.0, -7.0, 11.0)
        S = mat4_scaling(2.0, 3.0, 4.0)
        M = T * S
        p = Vec3(1.0, 1.0, 1.0)
        @test mat4_transform_point(M, p) == mat4_transform_point(T, mat4_transform_point(S, p))

        T * S
        @test_opt_alloc 64 T * S
    end

    @testset "Mat4 perspective projection" begin
        P = mat4_perspective(π/4, 1.0, 0.1, 100.0)
        # Point at origin along -Z should project to center
        p_clip = mat4_transform_vec4(P, Vec4(0.0, 0.0, -1.0, 1.0))
        ndc_x = p_clip.x / p_clip.w
        ndc_y = p_clip.y / p_clip.w
        @test ndc_x ≈ 0.0 atol=1e-10
        @test ndc_y ≈ 0.0 atol=1e-10
    end

    @testset "Quaternion" begin
        q = quat_from_euler(0.0, 0.0, π/2)
        m = quat_to_mat4(q)
        p = mat4_transform_point(m, Vec3(1.0, 0.0, 0.0))
        @test p.x ≈ 0.0 atol=1e-10
        @test p.y ≈ 1.0 atol=1e-10

        # Identity quaternion
        qi = Quaternion()
        mi = quat_to_mat4(qi)
        pi = mat4_transform_point(mi, Vec3(5.0, 3.0, 1.0))
        @test pi.x ≈ 5.0 && pi.y ≈ 3.0 && pi.z ≈ 1.0
    end

    @testset "Camera zoom projection" begin
        pbase = PerspectiveCamera(fov=π / 4, aspect=1.5, near=0.1, far=100.0)
        pzoom = PerspectiveCamera(fov=π / 4, aspect=1.5, near=0.1, far=100.0,
                                  zoom=2.0)
        P0 = projection_matrix(pbase)
        P1 = projection_matrix(pzoom)
        @test pbase.zoom ≈ 1.0
        @test P1.e[1] ≈ 2.0 * P0.e[1]
        @test P1.e[6] ≈ 2.0 * P0.e[6]
        pzoom.zoom = 0.0
        @test_throws ArgumentError projection_matrix(pzoom)
        @test_throws ArgumentError PerspectiveCamera(zoom=0.0)

        obase = OrthographicCamera(left=-2.0, right=2.0, bottom=-1.0, top=1.0,
                                   near=0.1, far=100.0)
        ozoom = OrthographicCamera(left=-2.0, right=2.0, bottom=-1.0, top=1.0,
                                   near=0.1, far=100.0, zoom=2.0)
        O0 = projection_matrix(obase)
        O1 = projection_matrix(ozoom)
        @test obase.zoom ≈ 1.0
        @test O1.e[1] ≈ 2.0 * O0.e[1]
        @test O1.e[6] ≈ 2.0 * O0.e[6]
        ozoom.zoom = Inf
        @test_throws ArgumentError projection_matrix(ozoom)
        @test_throws ArgumentError OrthographicCamera(zoom=-1.0)
    end

    @testset "BoxGeometry" begin
        geo = BoxGeometry(width=2.0, height=2.0, depth=2.0)
        @test geo.n_vertices == 24  # 4 per face × 6 faces
        @test geo.n_faces == 12     # 2 triangles per face × 6 faces
        @test length(geo.positions) == 24 * 3
        @test length(geo.normals) == 24 * 3
        @test length(geo.indices) == 12 * 3

        # Check vertex range
        for k in 1:3:length(geo.positions)
            @test -1.0 <= geo.positions[k] <= 1.0
            @test -1.0 <= geo.positions[k+1] <= 1.0
            @test -1.0 <= geo.positions[k+2] <= 1.0
        end

        # Default single-segment output keeps the historical first face layout.
        @test get_face(geo, 1) == (1, 2, 3)
        @test get_vertex(geo, 1) == Vec3(-1.0, -1.0, 1.0)
        @test get_vertex(geo, 2) == Vec3(1.0, -1.0, 1.0)
        @test get_vertex(geo, 3) == Vec3(1.0, 1.0, 1.0)
        @test_opt_alloc 4096 BoxGeometry(width=2.0, height=2.0, depth=2.0)

        seg = BoxGeometry(width=2.0, height=4.0, depth=6.0,
                          width_segments=2, height_segments=3, depth_segments=4)
        @test seg.n_vertices == 2 * ((2 + 1) * (3 + 1) +
                                     (2 + 1) * (4 + 1) +
                                     (4 + 1) * (3 + 1))
        @test seg.n_faces == 4 * (2 * 3 + 2 * 4 + 4 * 3)
        seg_box = compute_bounding_box(seg)
        @test seg_box.min.x ≈ -1.0 && seg_box.min.y ≈ -2.0 && seg_box.min.z ≈ -3.0
        @test seg_box.max.x ≈ 1.0 && seg_box.max.y ≈ 2.0 && seg_box.max.z ≈ 3.0
        @test all(0.0 <= uv <= 1.0 for uv in seg.uvs)
        for fi in 1:seg.n_faces
            fn = compute_face_normal(seg, fi)
            for vi in get_face(seg, fi)
                @test dot(fn, get_normal(seg, vi)) > 0.99
            end
        end
        @test_opt_alloc 65536 BoxGeometry(width=2.0, height=4.0, depth=6.0,
                                          width_segments=8, height_segments=8,
                                          depth_segments=8)
        @test_throws ArgumentError BoxGeometry(width_segments=0)
        @test_throws ArgumentError BoxGeometry(height_segments=1.5)
    end

    @testset "SphereGeometry" begin
        geo = SphereGeometry(radius=2.0, width_segments=16, height_segments=8)
        @test geo.n_vertices > 0
        @test geo.n_faces > 0

        # Check radius: all vertices should be at distance ~2 from origin
        for vi in 1:geo.n_vertices
            v = get_vertex(geo, vi)
            r = norm(v)
            @test r ≈ 2.0 atol=1e-10
        end
        @test_opt_alloc 24576 SphereGeometry(radius=2.0, width_segments=16, height_segments=8)
    end

    @testset "PlaneGeometry" begin
        geo = PlaneGeometry(width=4.0, height=4.0)
        @test geo.n_vertices == 4
        @test geo.n_faces == 2
        @test_opt_alloc 1024 PlaneGeometry(width=4.0, height=4.0)
    end

    @testset "CylinderGeometry" begin
        geo = CylinderGeometry(radius_top=1.0, radius_bottom=1.0, height=2.0)
        @test geo.n_faces > 0
        @test geo.n_vertices > 0
        @test_opt_alloc 16384 CylinderGeometry(radius_top=1.0, radius_bottom=1.0,
                                               height=2.0)
        @test_opt_alloc 12288 ConeGeometry(radius=1.0, height=2.0)
    end

    @testset "TorusGeometry" begin
        geo = TorusGeometry(radius=2.0, tube=0.5)
        @test geo.n_faces > 0
        @test_opt_alloc 115000 TorusGeometry(radius=2.0, tube=0.5)
    end

    @testset "TorusKnotGeometry" begin
        geo = TorusKnotGeometry(radius=1.0, tube=0.4)
        @test geo.n_faces > 0
        @test geo.n_vertices > 0
        @test_opt_alloc 70000 TorusKnotGeometry(radius=1.0, tube=0.4)
    end

    @testset "RingGeometry" begin
        geo = RingGeometry(inner_radius=0.5, outer_radius=1.0)
        @test geo.n_faces > 0
        @test geo.n_vertices > 0
        @test all(isfinite, RingGeometry(inner_radius=0.0, outer_radius=0.0).uvs)
        @test_opt_alloc 8192 RingGeometry(inner_radius=0.5, outer_radius=1.0)
    end

    @testset "CircleGeometry" begin
        geo = CircleGeometry(radius=1.0)
        @test geo.n_faces == 32
        @test geo.n_vertices == 34
        @test all(isfinite, geo.positions)
        @test all(isfinite, geo.normals)
        @test all(isfinite, geo.uvs)
        @test_opt_alloc 4096 CircleGeometry(radius=1.0)
    end

    @testset "Scene graph" begin
        scene = Scene()
        geo = BoxGeometry()
        mat = MeshBasicMaterial(color=Color3(1.0, 0.0, 0.0))
        mesh = Mesh(geo, mat; name="RedCube")
        add!(scene, mesh)

        @test length(get_children(scene)) == 1
        @test get_parent(mesh) === scene
        @test mesh.name == "RedCube"

        meshes = collect_meshes(scene)
        @test length(meshes) == 1
        @test meshes[1] === mesh

        mesh_collect_scene = Scene()
        for _ in 1:64
            add!(mesh_collect_scene, Mesh(geo, mat))
        end
        hidden_mesh_group = Group()
        hidden_mesh_group.visible = false
        add!(hidden_mesh_group, Mesh(geo, mat))
        add!(mesh_collect_scene, hidden_mesh_group)
        mesh_collection = collect_meshes(mesh_collect_scene)
        @test length(mesh_collection) == 64
        @test_opt_alloc 2048 collect_meshes(mesh_collect_scene)

        instanced_scene = Scene()
        for _ in 1:64
            add!(instanced_scene, InstancedMesh(geo, mat, 1))
        end
        hidden_instanced = Group()
        hidden_instanced.visible = false
        hidden_mesh = InstancedMesh(geo, mat, 1)
        add!(hidden_instanced, hidden_mesh)
        add!(instanced_scene, hidden_instanced)
        instanced = collect_instanced(instanced_scene)
        @test length(instanced) == 65
        @test instanced[end] === hidden_mesh
        @test_opt_alloc 2048 collect_instanced(instanced_scene)

        parent = Group()
        parent.position = Vec3(1.0, 2.0, 3.0)
        child = Mesh(BoxGeometry(), MeshBasicMaterial())
        child.position = Vec3(0.5, -0.25, 1.0)
        add!(parent, child)
        @test compute_world_matrix(child).e ==
              (compute_local_matrix(parent) * compute_local_matrix(child)).e

        compute_world_matrix(mesh)
        @test_opt_alloc 64 compute_world_matrix(mesh)
        compute_world_matrix(child)
        @test_opt_alloc 64 compute_world_matrix(child)
    end

    @testset "Camera projection" begin
        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        P = projection_matrix(cam)
        V = view_matrix(cam)
        @test mat4_get(P, 1, 1) != 0.0
        @test mat4_get(V, 1, 1) != 0.0
    end

    @testset "Materials" begin
        m1 = MeshBasicMaterial(color=Color3(1.0, 0.0, 0.0))
        @test m1.color.r ≈ 1.0

        m2 = MeshPhongMaterial(shininess=64.0)
        @test m2.shininess ≈ 64.0

        m3 = MeshStandardMaterial(metalness=0.8, roughness=0.2)
        @test m3.metalness ≈ 0.8
        @test m3.roughness ≈ 0.2
        m4 = MeshStandardMaterial(color=Color3(1, 0, 0))
        @test m4.color === Color3(1.0, 0.0, 0.0)
        m5 = MeshPhysicalMaterial(sheen_color=Color3(1, 1, 1))
        @test m5.sheen_color === Color3(1.0, 1.0, 1.0)
        @test m5.thickness ≈ 0.0
        @test m5.attenuation_distance ≈ 0.0
        @test m5.attenuation_color === Color3(1.0, 1.0, 1.0)
        @test m5.anisotropy ≈ 0.0
        @test m5.anisotropy_rotation ≈ 0.0
        @test m5.anisotropy_map === nothing

        dashed = LineDashedMaterial(color=Color3(0.2, 0.4, 0.8),
                                    linewidth=2.0, scale=0.5,
                                    dash_size=1.25, gap_size=0.75,
                                    opacity=0.8, depth_write=false)
        @test dashed.color == Color3(0.2, 0.4, 0.8)
        @test dashed.linewidth ≈ 2.0
        @test dashed.scale ≈ 0.5
        @test dashed.dash_size ≈ 1.25
        @test dashed.gap_size ≈ 0.75
        @test dashed.opacity ≈ 0.8
        @test dashed.depth_write == false
        alias_dashed = LineDashedMaterial(dashSize=2.0, gapSize=0.5)
        @test alias_dashed.dash_size ≈ 2.0
        @test alias_dashed.gap_size ≈ 0.5
        @test_throws ArgumentError LineDashedMaterial(dash_size=-1.0)
        @test_throws ArgumentError LineDashedMaterial(dash_size=0.0, gap_size=0.0)
    end

    @testset "Dashed line distances" begin
        strip = BufferGeometry(Float64[0,0,0, 3,0,0, 3,4,0],
                               Float64[], Float64[], Int[], 3, 0)
        @test compute_line_distances!(strip; mode=:line_strip) === strip
        strip_attr = get_attribute(strip, :lineDistance)
        @test strip_attr.item_size == 1
        @test strip_attr.data ≈ [0.0, 3.0, 7.0]

        segments = BufferGeometry(Float64[0,0,0, 0,0,5, 1,1,1, 4,5,1],
                                  Float64[], Float64[], Int[], 4, 0)
        compute_line_distances!(segments; mode=:lines)
        @test get_attribute(segments, :lineDistance).data ≈ [0.0, 5.0, 0.0, 5.0]

        indexed = BufferGeometry(Float64[0,0,0, 1,0,0, 2,0,0],
                                 Float64[], Float64[], Int[1, 2, 2, 3], 3, 0)
        @test_throws ArgumentError compute_line_distances!(indexed; mode=:lines)
        @test_throws ArgumentError compute_line_distances!(strip; mode=:bad)

        function line_distance_test_geo(n; indexed=false)
            positions = Vector{Float64}(undef, 3n)
            for i in 1:n
                positions[3i - 2] = i
                positions[3i - 1] = 0.0
                positions[3i] = 0.0
            end
            BufferGeometry(positions, Float64[], Float64[], indexed ? collect(1:n) : Int[], n, 0)
        end
        unindexed_alloc = line_distance_test_geo(100)
        indexed_alloc = line_distance_test_geo(100; indexed=true)
        compute_line_distances!(unindexed_alloc; mode=:line_strip)
        unindexed_attr = get_attribute(unindexed_alloc, :lineDistance)
        compute_line_distances!(indexed_alloc; mode=:line_strip)
        indexed_attr = get_attribute(indexed_alloc, :lineDistance)
        @test_opt_alloc 256 compute_line_distances!(unindexed_alloc; mode=:line_strip)
        @test get_attribute(unindexed_alloc, :lineDistance) === unindexed_attr
        @test_opt_alloc 64 compute_line_distances!(indexed_alloc; mode=:line_strip)
        @test get_attribute(indexed_alloc, :lineDistance) === indexed_attr
    end

    @testset "Shading — Lambert" begin
        n = Vec3(0.0, 0.0, 1.0)
        l = Vec3(0.0, 0.0, 1.0)  # light from front
        lc = Color3(1.0, 1.0, 1.0)
        sc = Color3(0.5, 0.5, 0.5)
        c = shade_lambert(n, l, lc, 1.0, sc)
        @test c.r ≈ 0.5  # full illumination

        # Light from behind
        lb = Vec3(0.0, 0.0, -1.0)
        cb = shade_lambert(n, lb, lc, 1.0, sc)
        @test cb.r ≈ 0.0  # no illumination

        public_light_geo = BoxGeometry(width_segments=10, height_segments=10,
                                       depth_segments=10)
        public_light_scene_colors = Vector{Color3{Float64}}(undef,
                                                            public_light_geo.n_faces)
        public_light_abstract_colors = similar(public_light_scene_colors)
        public_scene_lights = Diff3D.SceneLight[DirectionalLight()]
        public_abstract_lights = AbstractLight[DirectionalLight()]
        public_light_world = Mat4()
        public_light_material = MeshLambertMaterial()
        public_light_camera = Vec3(0.0, 0.0, 5.0)
        Diff3D.shade_mesh_faces!(public_light_scene_colors, public_light_geo,
                                 public_light_world, public_light_material,
                                 public_scene_lights, public_light_camera)
        Diff3D.shade_mesh_faces!(public_light_abstract_colors, public_light_geo,
                                 public_light_world, public_light_material,
                                 public_abstract_lights, public_light_camera)
        @test public_light_abstract_colors == public_light_scene_colors
        @test_opt_alloc 512 Diff3D.shade_mesh_faces!(public_light_abstract_colors,
                                                     public_light_geo,
                                                     public_light_world,
                                                     public_light_material,
                                                     public_abstract_lights,
                                                     public_light_camera)
        custom_public_light = TestDirectionalLikeLight(Color3(1.0, 1.0, 1.0),
                                                       1.0, Vec3(0.0, 0.0, 1.0))
        custom_public_abstract = AbstractLight[custom_public_light]
        custom_public_concrete = TestDirectionalLikeLight[custom_public_light]
        custom_abstract_colors = similar(public_light_scene_colors)
        custom_concrete_colors = similar(public_light_scene_colors)
        Diff3D.shade_mesh_faces!(custom_abstract_colors, public_light_geo,
                                 public_light_world, public_light_material,
                                 custom_public_abstract, public_light_camera)
        Diff3D.shade_mesh_faces!(custom_concrete_colors, public_light_geo,
                                 public_light_world, public_light_material,
                                 custom_public_concrete, public_light_camera)
        @test custom_abstract_colors == custom_concrete_colors
        @test_opt_alloc 2048 Diff3D.shade_mesh_faces!(custom_abstract_colors,
                                                      public_light_geo,
                                                      public_light_world,
                                                      public_light_material,
                                                      custom_public_abstract,
                                                      public_light_camera)
        empty_mapped_material = MeshLambertMaterial(
            map=Texture(ones(Float64, 1, 1, 3); colorspace=:linear))
        empty_mapped_lights = AbstractLight[]
        Diff3D.shade_mesh_faces!(custom_abstract_colors, public_light_geo,
                                 public_light_world, empty_mapped_material,
                                 empty_mapped_lights, public_light_camera)

        mapped_vc_geo = BoxGeometry(width_segments=10, height_segments=10,
                                    depth_segments=10)
        set_attribute!(mapped_vc_geo, :color,
                       fill(0.5, mapped_vc_geo.n_vertices * 3), 3)
        mapped_vc_tex = Texture(ones(Float64, 1, 1, 3);
                                filter=:nearest, colorspace=:linear)
        mapped_vc_dir = DirectionalLight(intensity=0.4,
                                         position=Vec3(1.0, 2.0, 3.0))
        mapped_vc_dir.target = Vec3(0.0, 0.0, 0.0)
        mapped_vc_lights = Diff3D.SceneLight[AmbientLight(intensity=0.7),
                                             mapped_vc_dir]
        mapped_vc_world = Mat4()
        mapped_vc_camera = Vec3(0.0, 0.0, 5.0)
        mapped_vc_material = MeshLambertMaterial(map=mapped_vc_tex,
                                                 vertex_colors=true)
        mapped_vc_equiv_material = MeshLambertMaterial(
            color=Color3(0.5, 0.5, 0.5), map=mapped_vc_tex)
        mapped_vc_actual = Vector{Color3{Float64}}(undef,
                                                   mapped_vc_geo.n_faces)
        mapped_vc_expected = similar(mapped_vc_actual)
        Diff3D.shade_mesh_faces!(mapped_vc_actual, mapped_vc_geo,
                                 mapped_vc_world, mapped_vc_material,
                                 mapped_vc_lights, mapped_vc_camera)
        Diff3D.shade_mesh_faces!(mapped_vc_expected, mapped_vc_geo,
                                 mapped_vc_world, mapped_vc_equiv_material,
                                 mapped_vc_lights, mapped_vc_camera)
        @test mapped_vc_actual == mapped_vc_expected
        @test_opt_alloc 1024 Diff3D.shade_mesh_faces!(mapped_vc_actual,
                                                      mapped_vc_geo,
                                                      mapped_vc_world,
                                                      mapped_vc_material,
                                                      mapped_vc_lights,
                                                      mapped_vc_camera)
    end

    @testset "Shading — Phong" begin
        n = Vec3(0.0, 0.0, 1.0)
        l = Vec3(0.0, 0.0, 1.0)
        v = Vec3(0.0, 0.0, 1.0)
        lc = Color3(1.0, 1.0, 1.0)
        dc = Color3(0.5, 0.5, 0.5)
        sc = Color3(1.0, 1.0, 1.0)
        c = shade_phong(n, l, v, lc, 1.0, dc, sc, 30.0)
        @test c.r > 0.5  # diffuse + specular > diffuse alone
