    @testset "RenderTarget" begin
        rt = RenderTarget(64, 48)
        @test rt.width == 64
        @test rt.height == 48
        @test size(rt.color) == (48, 64, 3)
        @test all(rt.color .== 0.0)

        clear!(rt, Color3(0.2, 0.3, 0.4))
        @test rt.color[1, 1, 1] ≈ 0.2
        @test rt.color[1, 1, 2] ≈ 0.3
        @test rt.color[1, 1, 3] ≈ 0.4
    end

    @testset "CPU rasterizer — basic render" begin
        scene = Scene(background=Color3(0.1, 0.1, 0.1))
        geo = BoxGeometry(width=1.0, height=1.0, depth=1.0)
        mat = MeshPhongMaterial(color=Color3(0.8, 0.2, 0.2))
        mesh = Mesh(geo, mat)
        add!(scene, mesh)

        light = DirectionalLight(color=Color3(1.0, 1.0, 1.0), intensity=1.0,
                                 position=Vec3(5.0, 5.0, 5.0))
        add!(scene, light)

        ambient = AmbientLight(intensity=0.3)
        add!(scene, ambient)

        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        cam.position = Vec3(0.0, 0.0, 3.0)

        rt = RenderTarget(32, 32)
        render!(rt, scene, cam)

        # Center pixel should not be background
        cy, cx = 16, 16
        pixel_r = rt.color[cy, cx, 1]
        @test pixel_r > 0.1  # something rendered, not just background

        # Corner pixel should be background (cube is small relative to viewport)
        corner_r = rt.color[1, 1, 1]
        @test corner_r ≈ 0.1 atol=1e-12
    end

    @testset "Edge function" begin
        # Triangle (0,0), (10,0), (0,10) — CW winding gives negative area
        ef = edge_function(0.0, 0.0, 10.0, 0.0, 0.0, 10.0)
        @test abs(ef) ≈ 100.0  # |signed area * 2|

        # Barycentric coords for point (3,3) inside triangle
        w0 = edge_function(10.0, 0.0, 0.0, 10.0, 3.0, 3.0) / ef
        w1 = edge_function(0.0, 10.0, 0.0, 0.0, 3.0, 3.0) / ef
        w2 = edge_function(0.0, 0.0, 10.0, 0.0, 3.0, 3.0) / ef
        @test w0 + w1 + w2 ≈ 1.0 atol=1e-10
    end

    @testset "Soft rasterizer — signed distance" begin
        # Point at center of triangle (0,0)-(10,0)-(0,10) should be positive
        d = signed_distance_to_triangle(2.0, 2.0, 0.0, 0.0, 10.0, 0.0, 0.0, 10.0)
        @test d > 0.0

        # Point far outside should be negative
        d_out = signed_distance_to_triangle(-5.0, -5.0, 0.0, 0.0, 10.0, 0.0, 0.0, 10.0)
        @test d_out < 0.0
    end

    @testset "Soft rasterizer — basic render" begin
        verts = [Vec3(-0.5, -0.5, 0.0), Vec3(0.5, -0.5, 0.0),
                 Vec3(0.5, 0.5, 0.0), Vec3(-0.5, 0.5, 0.0)]
        faces = [(1, 2, 3), (1, 3, 4)]
        colors = [Color3(1.0, 0.0, 0.0), Color3(0.0, 1.0, 0.0)]

        vp = mat4_perspective(π/4, 1.0, 0.1, 100.0) *
             mat4_look_at(Vec3(0.0,0.0,3.0), Vec3(0.0,0.0,0.0), Vec3(0.0,1.0,0.0))
        config = SoftRasterizerConfig(sigma=1e-2, gamma=1.0)

        img = soft_render(verts, faces, colors, vp, 16, 16, config)
        @test size(img) == (16, 16, 3)
        # Center pixel should have some color (not just black background)
        center_brightness = img[8, 8, 1] + img[8, 8, 2] + img[8, 8, 3]
        @test center_brightness > 0.01
        @test_opt_alloc 6900 soft_render(verts, faces, colors, vp, 16, 16, config)
        padded_faces = [faces; fill((1, 1, 1), 7)]
        padded_colors = [colors; fill(Color3(0.0, 0.0, 0.0), 7)]
        padded_img = soft_render(verts, padded_faces, padded_colors, vp, 16, 16, config)
        @test maximum(abs.(img .- padded_img)) < 1e-12

        empty_soft_cfg = SoftRasterizerConfig(sigma=0.5, gamma=0.1,
                                              bg_color=Color3(0.2, 0.3, 0.4))
        empty_soft_img = soft_render(Vec3{Float64}[], NTuple{3,Int}[],
                                     Color3{Float64}[], Mat4{Float64}(),
                                     32, 32, empty_soft_cfg)
        @test all(==(0.2), @view empty_soft_img[:, :, 1])
        @test all(==(0.3), @view empty_soft_img[:, :, 2])
        @test all(==(0.4), @view empty_soft_img[:, :, 3])
        @test_opt_alloc 25100 soft_render(Vec3{Float64}[], NTuple{3,Int}[],
                                          Color3{Float64}[], Mat4{Float64}(),
                                          32, 32, empty_soft_cfg)

        behind_soft_verts = [Vec3(-0.5, -0.5, 1.0),
                             Vec3(0.5, -0.5, 1.0),
                             Vec3(0.0, 0.5, 1.0)]
        behind_soft_img = soft_render(behind_soft_verts, [(1, 2, 3)],
                                      [Color3(1.0, 0.0, 0.0)],
                                      mat4_perspective(π/4, 1.0, 0.1, 100.0),
                                      32, 32, empty_soft_cfg)
        @test all(==(0.2), @view behind_soft_img[:, :, 1])
        @test all(==(0.3), @view behind_soft_img[:, :, 2])
        @test all(==(0.4), @view behind_soft_img[:, :, 3])

        near_cross_verts = [Vec3(-0.6, -0.6, -0.05),
                            Vec3(0.6, -0.6, -1.0),
                            Vec3(0.0, 0.6, -1.0)]
        near_cross_img = soft_render(near_cross_verts, [(1, 2, 3)],
                                     [Color3(1.0, 1.0, 1.0)],
                                     mat4_perspective(π/4, 1.0, 0.1, 100.0),
                                     32, 32,
                                     SoftRasterizerConfig(sigma=0.5, gamma=0.1))
        @test sum(near_cross_img) > 1.0

        soft_tail_verts = [Vec3(-1.0, 0.0, 0.0),
                           Vec3(-0.6, 0.0, 0.0),
                           Vec3(-1.0, 0.4, 0.0)]
        soft_tail_img = soft_render(soft_tail_verts, [(1, 2, 3)],
                                    [Color3(1.0, 1.0, 1.0)],
                                    Mat4{Float64}(), 256, 256,
                                    SoftRasterizerConfig(sigma=100.0, gamma=1.0))
        @test soft_tail_img[50, 200, 1] > 0.01

        one_face_verts = [verts[1], verts[2], verts[3]]
        one_face_faces = [(1, 2, 3)]
        one_face_colors = [colors[1]]
        soft_render(one_face_verts, one_face_faces, one_face_colors, vp, 16, 16, config)
        @test_opt_alloc 6700 soft_render(one_face_verts, one_face_faces, one_face_colors,
                                         vp, 16, 16, config)
        one_face_rf = vertex_render_fn(one_face_faces, one_face_colors, vp, 16, 16;
                                       sigma=1e-2, gamma=1.0)
        one_face_params = [-0.5, -0.5, 0.0, 0.5, -0.5, 0.0, 0.5, 0.5, 0.0]
        one_face_rf(one_face_params)
        @test_opt_alloc 7300 one_face_rf(one_face_params)
        one_face_ws = SoftRenderWorkspace()
        one_face_rf_ws = vertex_render_fn(one_face_faces, one_face_colors, vp, 16, 16;
                                          sigma=1e-2, gamma=1.0, workspace=one_face_ws)
        @test one_face_rf_ws(one_face_params) == one_face_rf(one_face_params)
        @test_opt_alloc 1024 one_face_rf_ws(one_face_params)

        soft_verts = Vec3{Float64}[]
        soft_faces = NTuple{3,Int}[]
        soft_colors = Color3{Float64}[]
        for iy in 0:15, ix in 0:15
            x = -0.9 + 1.8 * ix / 16
            y = -0.9 + 1.8 * iy / 16
            s = 0.8 / 16
            base = length(soft_verts)
            push!(soft_verts, Vec3(x, y, 0.0), Vec3(x + s, y, 0.0), Vec3(x, y + s, 0.0))
            push!(soft_faces, (base + 1, base + 2, base + 3))
            push!(soft_colors, Color3(1.0, 0.4, 0.2))
        end
        soft_render(soft_verts, soft_faces, soft_colors, Mat4{Float64}(), 16, 16, config)
        @test_opt_alloc 85000 soft_render(soft_verts, soft_faces, soft_colors, Mat4{Float64}(),
                                          16, 16, config)
        soft_ws = SoftRenderWorkspace()
        soft_ws_img = soft_render(soft_verts, soft_faces, soft_colors, Mat4{Float64}(),
                                  16, 16, config; workspace=soft_ws)
        @test soft_ws_img == soft_render(soft_verts, soft_faces, soft_colors,
                                         Mat4{Float64}(), 16, 16, config)
        @test !isempty(soft_ws.tile_counts)
        @test_opt_alloc 512 soft_render(soft_verts, soft_faces, soft_colors,
                                        Mat4{Float64}(), 16, 16, config;
                                        workspace=soft_ws)
        setup_soft(_p) = (soft_verts, soft_faces, soft_colors, Mat4{Float64}(),
                          Color3(0.0, 0.0, 0.0))
        diff_ws = SoftRenderWorkspace()
        diff_img = differentiable_render([0.0], setup_soft, 16, 16;
                                         sigma=1e-2, gamma=1.0, workspace=diff_ws)
        @test diff_img == soft_render(soft_verts, soft_faces, soft_colors,
                                      Mat4{Float64}(), 16, 16, config)
        @test_opt_alloc 512 differentiable_render([0.0], setup_soft, 16, 16;
                                                  sigma=1e-2, gamma=1.0,
                                                  workspace=diff_ws)

        soft_scene = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(soft_scene, AmbientLight(intensity=0.2))
        for i in 1:12
            mesh = Mesh(BoxGeometry(width=1.0, height=1.0, depth=1.0),
                        MeshLambertMaterial(color=Color3(0.8, 0.2, 0.1)))
            mesh.position = Vec3((i % 6) * 1.3, (i ÷ 6) * 1.3, 0.0)
            add!(soft_scene, mesh)
        end
        soft_scene_cam = PerspectiveCamera(aspect=1.0)
        soft_scene_cam.position = Vec3(4.0, 4.0, 16.0)
        soft_scene_cam.target = Vec3(3.0, 1.0, 0.0)
        soft_scene_img = soft_render_scene(soft_scene, soft_scene_cam, 12, 12)
        @test size(soft_scene_img) == (12, 12, 3)
        @test all(isfinite, soft_scene_img)
        @test_opt_alloc 65536 soft_render_scene(soft_scene, soft_scene_cam, 12, 12)
        soft_scene_ws = SoftRenderSceneWorkspace()
        soft_scene_ws_img = soft_render_scene(soft_scene, soft_scene_cam, 12, 12;
                                              workspace=soft_scene_ws)
        @test soft_scene_ws_img == soft_scene_img
        @test length(soft_scene_ws.vertices) == sum(Diff3D._mesh_geometry(m).n_vertices
                                                    for m in collect_meshes(soft_scene))
        @test_opt_alloc 4096 soft_render_scene(soft_scene, soft_scene_cam, 12, 12;
                                               workspace=soft_scene_ws)
        many_basic_soft_scene = Scene(background=Color3(0.0, 0.0, 0.0))
        for i in 1:100
            mesh = Mesh(PlaneGeometry(), MeshBasicMaterial(color=Color3(1.0, 0.0, 0.0)))
            mesh.position = Vec3(2.0 * i, 0.0, 0.0)
            add!(many_basic_soft_scene, mesh)
        end
        many_basic_soft_cam = OrthographicCamera(left=-1.0, right=1.0, top=1.0,
                                                 bottom=-1.0, near=0.1, far=10.0)
        many_basic_soft_cam.position = Vec3(0.0, 0.0, 2.0)
        many_basic_soft_cam.target = Vec3(0.0, 0.0, 0.0)
        many_basic_soft_ws = SoftRenderSceneWorkspace()
        soft_render_scene(many_basic_soft_scene, many_basic_soft_cam, 1, 1;
                          workspace=many_basic_soft_ws)
        @test_opt_alloc 4096 soft_render_scene(many_basic_soft_scene,
                                               many_basic_soft_cam, 1, 1;
                                               workspace=many_basic_soft_ws)
    end

    @testset "Loss functions" begin
        img1 = deterministic_array(8, 8, 3)
        img2 = copy(img1)

        @test loss_mse(img1, img2) ≈ 0.0 atol=1e-15
        @test loss_l1(img1, img2) ≈ 0.0 atol=1e-15

        # Different images should have positive loss
        img3 = reverse(img1; dims=1)
        @test loss_mse(img1, img3) > 0.0
        @test loss_l1(img1, img3) > 0.0
    end

    @testset "ForwardDiff gradient through soft render" begin
        # Simple test: move a triangle along x, compute gradient of center pixel
        function _test_render_offset(x_offset)
            T = eltype(x_offset)
            verts = [Vec3(T(-0.5) + x_offset[1], T(-0.5), zero(T)),
                     Vec3(T(0.5) + x_offset[1], T(-0.5), zero(T)),
                     Vec3(zero(T) + x_offset[1], T(0.5), zero(T))]
            faces = [(1, 2, 3)]
            colors = [Color3(one(T), zero(T), zero(T))]
            vp = mat4_perspective(T(π/4), one(T), T(0.1), T(100)) *
                 mat4_look_at(Vec3(zero(T), zero(T), T(3)),
                              Vec3(zero(T), zero(T), zero(T)),
                              Vec3(zero(T), one(T), zero(T)))
            config = SoftRasterizerConfig(sigma=T(0.5), gamma=T(1.0),
                                          bg_color=Color3(zero(T), zero(T), zero(T)),
                                          eps=T(1e-8))
            img = soft_render(verts, faces, colors, vp, 8, 8, config)
            img[4, 4, 1]
        end

        grad = ForwardDiff.gradient(_test_render_offset, [0.0])
        @test length(grad) == 1
        @test isfinite(grad[1])

        # Numerical gradient for comparison
        f0 = _test_render_offset([0.0])
        f1 = _test_render_offset([0.001])
        fd_grad = (f1 - f0) / 0.001
        if abs(fd_grad) > 1e-10
            @test abs(grad[1] - fd_grad) / max(abs(fd_grad), 1e-8) < 1.0
        end
    end

    @testset "Numerical gradient utility" begin
        f(x) = sum(x .^ 2)
        g = numerical_gradient(f, [1.0, 2.0, 3.0])
        @test g[1] ≈ 2.0 atol=1e-4
        @test g[2] ≈ 4.0 atol=1e-4
        @test g[3] ≈ 6.0 atol=1e-4

        p = [1.0, 2.0, 3.0]
        f_mutating(x) = (s = sum(abs2, x); fill!(x, 0.0); s)
        @test numerical_gradient(f_mutating, p) ≈ [2.0, 4.0, 6.0] atol=1e-4
        @test p == [1.0, 2.0, 3.0]
        @test_throws ArgumentError numerical_gradient(f, p; δ=0.0)
        wide = collect(range(0.1, 1.0; length=64))
        @test_opt_alloc 1536 numerical_gradient(x -> sum(abs2, x), wide)
    end

    @testset "Inverse optimizers — descent and bounded workspace" begin
        function linear_image(p)
            img = Array{eltype(p),3}(undef, 1, 1, 2)
            img[1, 1, 1] = p[1]
            img[1, 1, 2] = p[2]
            img
        end
        target = Array{Float64,3}(undef, 1, 1, 2)
        target[1, 1, 1] = 1.0
        target[1, 1, 2] = -1.0
        p0 = [0.0, 0.0]
        loss0 = loss_mse(linear_image(p0), target)

        gd, gd_hist = inverse_render_optimize(p0, target, linear_image, loss_mse;
                                              lr=0.2, n_iters=8, verbose=false)
        @test length(gd_hist) == 8
        @test loss_mse(linear_image(gd), target) < loss0

        adam, adam_hist = inverse_render_adam(p0, target, linear_image, loss_mse;
                                              lr=0.1, n_iters=8, verbose=false)
        @test length(adam_hist) == 8
        @test loss_mse(linear_image(adam), target) < loss0
        @test_throws ArgumentError inverse_render_optimize(p0, target, linear_image, loss_mse;
                                                           n_iters=-1, verbose=false)
        @test_throws ArgumentError inverse_render_adam(p0, target, linear_image, loss_mse;
                                                       n_iters=-1, verbose=false)
        @test_throws ArgumentError inverse_render_optimize(p0, target, linear_image, loss_mse;
                                                           lr=NaN, n_iters=1, verbose=false)
        @test_throws ArgumentError inverse_render_adam(p0, target, linear_image, loss_mse;
                                                       β1=1.0, n_iters=1, verbose=false)
        @test_throws ArgumentError inverse_render_adam(p0, target, linear_image, loss_mse;
                                                       β2=NaN, n_iters=1, verbose=false)
        @test_throws ArgumentError inverse_render_adam(p0, target, linear_image, loss_mse;
                                                       ε=0.0, n_iters=1, verbose=false)
        gd_calls = Ref(0)
        gd_counting_image(p) = (gd_calls[] += 1; linear_image(p))
        inverse_render_optimize(p0, target, gd_counting_image, loss_mse;
                                lr=0.2, n_iters=4, verbose=false)
        @test gd_calls[] == 4
        adam_calls = Ref(0)
        adam_counting_image(p) = (adam_calls[] += 1; linear_image(p))
        inverse_render_adam(p0, target, adam_counting_image, loss_mse;
                            lr=0.1, n_iters=4, verbose=false)
        @test adam_calls[] == 4
        @test_opt_alloc 8192 inverse_render_optimize(p0, target, linear_image, loss_mse;
                                                     lr=0.2, n_iters=10, verbose=false)
        @test_opt_alloc 8192 inverse_render_adam(p0, target, linear_image, loss_mse;
                                                 lr=0.1, n_iters=10, verbose=false)

        wide_calls = Ref(0)
        function quadratic_image(p)
            wide_calls[] += 1
            T = eltype(p)
            img = Array{T,3}(undef, 1, 1, 1)
            s = zero(T)
            for x in p
                s += x * x
            end
            img[1, 1, 1] = s
            return img
        end
        wide = fill(0.1, 24)
        wide_target = zeros(1, 1, 1)
        wide_calls[] = 0
        inverse_render_optimize(wide, wide_target, quadratic_image, loss_mse;
                                lr=0.01, n_iters=1, verbose=false, ad=:auto)
        @test wide_calls[] == 1
        wide_calls[] = 0
        inverse_render_adam(wide, wide_target, quadratic_image, loss_mse;
                            lr=0.01, n_iters=1, verbose=false, ad=:auto)
        @test wide_calls[] == 1
        wide_calls[] = 0
        inverse_render_optimize(wide, wide_target, quadratic_image, loss_mse;
                                lr=0.01, n_iters=1, verbose=false, ad=:forward)
        @test wide_calls[] > 1
        function constant_image(p)
            img = Array{Float64,3}(undef, 1, 1, 1)
            img[1, 1, 1] = 0.0
            return img
        end
        _, const_hist = inverse_render_optimize(wide, wide_target, constant_image,
                                                loss_mse; lr=0.01, n_iters=1,
                                                verbose=false, ad=:auto)
        @test const_hist[1] == 0.0
        @test_throws ArgumentError inverse_render_optimize(wide, wide_target,
                                                          quadratic_image, loss_mse;
                                                          n_iters=1, verbose=false,
                                                          ad=:invalid)
    end

    @testset "I/O — PPM export" begin
        img = test_pattern(16, 16)
        @test size(img) == (16, 16, 3)
        # Just verify it doesn't error; we don't write to disk in tests
        tmpfile = tempname() * ".ppm"
        save_ppm(tmpfile, img)
        @test isfile(tmpfile)
        @test_opt_alloc 2048 save_ppm(tmpfile, img)
        rm(tmpfile)
    end

    @testset "Merge geometries" begin
        g1 = BoxGeometry()
        g2 = SphereGeometry(width_segments=8, height_segments=4)
        merged = merge_geometries([g1, g2])
        @test merged.n_vertices == g1.n_vertices + g2.n_vertices
        @test merged.n_faces == g1.n_faces + g2.n_faces
        @test_opt_alloc 8192 merge_geometries([g1, g2])
    end

    @testset "PNG/PDF checksum oracles" begin
        # CRC-32/ISO-HDLC standard check value for "123456789".
        @test Diff3D._crc32(Vector{UInt8}(codeunits("123456789"))) == 0xcbf43926
        # CRC of the IEND chunk type (no data) — fixed PNG constant.
        @test Diff3D._crc32(Vector{UInt8}(codeunits("IEND"))) == 0xae426082
        # Adler-32 of "Wikipedia" — canonical reference value.
        @test Diff3D._adler32(Vector{UInt8}(codeunits("Wikipedia"))) == 0x11e60398
    end

    @testset "I/O — PNG export structure" begin
        img = test_pattern(20, 12)   # width=20, height=12
        f = tempname() * ".png"
        save_png(f, img)
        @test isfile(f)
        bytes = read(f)
        @test bytes[1:8] == UInt8[137, 80, 78, 71, 13, 10, 26, 10]   # PNG signature
        # IHDR width/height (big-endian) at byte offset 16 (sig 8 + len 4 + type 4).
        w = (Int(bytes[17]) << 24) | (Int(bytes[18]) << 16) | (Int(bytes[19]) << 8) | Int(bytes[20])
        h = (Int(bytes[21]) << 24) | (Int(bytes[22]) << 16) | (Int(bytes[23]) << 8) | Int(bytes[24])
        @test w == 20 && h == 12
        @test bytes[end-7:end] == UInt8[0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82]  # IEND + CRC
        rm(f)
    end

    @testset "I/O — PDF export structure" begin
        img = test_pattern(16, 16)
        f = tempname() * ".pdf"
        save_pdf(f, img)
        @test isfile(f)
        bytes = read(f)
        @test String(bytes[1:8]) == "%PDF-1.4"
        tail = String(bytes[max(1, end-16):end])
        @test occursin("%%EOF", tail)
        @test_opt_alloc 10000 save_pdf(f, img)
        rm(f)
    end

