    @testset "Ambient is uniform fill, not directional (regression)" begin
        mat = MeshLambertMaterial(color=Color3(0.6, 0.6, 0.6))
        amb = AbstractLight[AmbientLight(intensity=0.5)]
        up   = shade_face(Vec3(0.0,  1.0, 0.0), Vec3(0.0, 0.0, 1.0), Vec3(), mat, amb)
        down = shade_face(Vec3(0.0, -1.0, 0.0), Vec3(0.0, 0.0, 1.0), Vec3(), mat, amb)
        @test up.r ≈ down.r              # ambient independent of surface orientation
        @test down.r > 0.0               # downward face not black under ambient
        @test up.r ≈ 0.6 * 0.5           # albedo × intensity
    end

    @testset "PBR metal not black under ambient (regression)" begin
        n = Vec3(0.0, 1.0, 0.0); v = Vec3(0.0, 0.0, 1.0)
        metal = MeshStandardMaterial(color=Color3(0.95, 0.78, 0.22),
                                     metalness=0.9, roughness=0.25)
        c = shade_face(n, v, Vec3(), metal, AbstractLight[AmbientLight(intensity=0.5)])
        @test (c.r + c.g + c.b) > 0.1    # metal reflects ambient, not black
        @test c.r > c.b                  # gold albedo preserved (red > blue)
    end

    @testset "Near-plane clipping — straddling geometry renders" begin
        # Large ground plane with corners behind the camera must render its
        # in-front portion (would vanish without near-plane clipping).
        scene = Scene(background=Color3(0.0, 0.0, 0.0))
        ground = Mesh(PlaneGeometry(width=50.0, height=50.0),
                      MeshLambertMaterial(color=Color3(0.85, 0.85, 0.85)))
        ground.rotation = Euler(-π/2, 0.0, 0.0)
        add!(scene, ground)
        add!(scene, AmbientLight(intensity=1.0))
        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        cam.position = Vec3(0.0, 2.0, 0.0)
        cam.target = Vec3(0.0, 0.0, -5.0)
        rt = RenderTarget(32, 32)
        render!(rt, scene, cam)
        lit = count(>(0.1), @view rt.color[:, :, 1])
        @test lit > 50                   # floor visible across many pixels
    end

    @testset "Smooth shading — continuity and correctness" begin
        scene = Scene(background=Color3(0.0, 0.0, 0.0))
        sph = Mesh(SphereGeometry(radius=1.0, width_segments=24, height_segments=12),
                   MeshLambertMaterial(color=Color3(0.8, 0.3, 0.3)))
        add!(scene, sph)
        add!(scene, AmbientLight(intensity=0.2))
        d = DirectionalLight(intensity=0.9, position=Vec3(3.0, 3.0, 4.0))
        d.target = Vec3(0.0, 0.0, 0.0)
        add!(scene, d)
        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        cam.position = Vec3(0.0, 0.0, 4.0)

        rtf = RenderTarget(100, 100); render!(rtf, scene, cam; shading=:flat)
        rts = RenderTarget(100, 100); render!(rts, scene, cam; shading=:smooth)

        # Same silhouette: both light a comparable number of pixels.
        litf = count(>(0.05), @view rtf.color[:, :, 1])
        lits = count(>(0.05), @view rts.color[:, :, 1])
        @test litf > 1000 && lits > 1000
        @test abs(lits - litf) < 0.1 * litf

        # Smooth shading yields a continuous gradient: many more distinct shades.
        uniq(rt) = length(unique(round.(vec(rt.color[:, :, 1]), digits=3)))
        @test uniq(rts) > 5 * uniq(rtf)
        smooth_cache = RenderCache()
        render!(rts, scene, cam; shading=:smooth, cache=smooth_cache)
        @test_opt_alloc 4096 render!(rts, scene, cam; shading=:smooth, cache=smooth_cache)

        # Invalid shading mode is rejected.
        @test_throws ArgumentError render!(RenderTarget(8, 8), scene, cam; shading=:bogus)
    end

    @testset "Smooth shading — constant normals match analytic Lambert" begin
        # A front-facing quad with all-front normals, lit head-on: smooth-shaded
        # pixels must equal the Lambert value albedo·intensity (N·L = 1).
        scene = Scene(background=Color3(0.0, 0.0, 0.0))
        quad = Mesh(PlaneGeometry(width=2.0, height=2.0),
                    MeshLambertMaterial(color=Color3(0.6, 0.4, 0.2)))
        add!(scene, quad)
        light = DirectionalLight(intensity=1.0, position=Vec3(0.0, 0.0, 5.0))
        light.target = Vec3(0.0, 0.0, 0.0)
        add!(scene, light)
        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        cam.position = Vec3(0.0, 0.0, 3.0)
        rt = RenderTarget(32, 32); render!(rt, scene, cam; shading=:smooth)
        # Center pixel: N=(0,0,1), L=(0,0,1) ⇒ N·L=1 ⇒ colour = albedo.
        @test rt.color[16, 16, 1] ≈ 0.6 atol=1e-6
        @test rt.color[16, 16, 2] ≈ 0.4 atol=1e-6
        @test rt.color[16, 16, 3] ≈ 0.2 atol=1e-6
    end

    @testset "RenderCache reuses per-frame renderer scratch" begin
        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        cam.position = Vec3(0.0, 0.0, 4.0)
        cam.target = Vec3(0.0, 0.0, 0.0)

        scene = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(scene, Mesh(BoxGeometry(), MeshLambertMaterial(color=Color3(0.8, 0.3, 0.2))))
        add!(scene, AmbientLight(intensity=0.3))
        add!(scene, DirectionalLight(intensity=0.7, position=Vec3(3.0, 3.0, 4.0)))
        rt_direct = RenderTarget(32, 32); render!(rt_direct, scene, cam)
        rt_cached = RenderTarget(32, 32); cache = RenderCache()
        render!(rt_cached, scene, cam; cache=cache)
        @test maximum(abs.(rt_cached.color .- rt_direct.color)) < 1e-12
        @test_opt_alloc 512 render!(rt_cached, scene, cam; cache=cache)

        wire_scene = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(wire_scene, Mesh(BoxGeometry(), MeshBasicMaterial(color=Color3(1.0, 1.0, 1.0),
                                                               wireframe=true)))
        wire_direct = RenderTarget(32, 32); render!(wire_direct, wire_scene, cam)
        wire_cached = RenderTarget(32, 32); wire_cache = RenderCache()
        render!(wire_cached, wire_scene, cam; cache=wire_cache)
        @test maximum(abs.(wire_cached.color .- wire_direct.color)) < 1e-12
        @test_opt_alloc 512 render!(wire_cached, wire_scene, cam; cache=wire_cache)

        tex = Texture(ones(Float64, 2, 2, 3); filter=:nearest, colorspace=:linear)
        sprite_scene = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(sprite_scene, Sprite(SpriteMaterial(color=Color3(1.0, 1.0, 1.0), map=tex)))
        sprite_direct = RenderTarget(32, 32); render!(sprite_direct, sprite_scene, cam)
        sprite_cached = RenderTarget(32, 32); sprite_cache = RenderCache()
        render!(sprite_cached, sprite_scene, cam; cache=sprite_cache)
        @test maximum(abs.(sprite_cached.color .- sprite_direct.color)) < 1e-12
        @test_opt_alloc 512 render!(sprite_cached, sprite_scene, cam; cache=sprite_cache)

        alpha_tex_data = ones(Float64, 2, 2, 4)
        alpha_tex_data[:, :, 4] .= 1.0
        alpha_tex = Texture(alpha_tex_data; filter=:nearest, colorspace=:linear)
        alpha_scene = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(alpha_scene,
             Mesh(BoxGeometry(),
                  MeshBasicMaterial(map=alpha_tex, alpha_test=0.5,
                                    side=:double)))
        alpha_pooled = RenderTarget(32, 32)
        alpha_cache = RenderCache()
        render_pooled!(alpha_pooled, alpha_scene, cam, alpha_cache)
        @test alpha_pooled.color[16, 16, 1] > 0.5
        @test_opt_alloc 1024 render_pooled!(alpha_pooled, alpha_scene, cam,
                                            alpha_cache)
        alpha_tiled = RenderTarget(32, 32)
        alpha_tiled_caches = [RenderCache()]
        render_tiled!(alpha_tiled, alpha_scene, cam; tiles=1,
                      cache=alpha_tiled_caches)
        @test alpha_tiled.color[16, 16, 1] > 0.5
        @test_opt_alloc 1024 render_tiled!(alpha_tiled, alpha_scene, cam;
                                           tiles=1, cache=alpha_tiled_caches)
    end

    @testset "Smooth shading — vertex colors are interpolated" begin
        geo = PlaneGeometry(width=2.0, height=2.0)
        set_attribute!(geo, :color, fill(0.0, 4 * geo.n_vertices), 4)
        cattr = get_attribute(geo, :color)
        for vi in 1:geo.n_vertices
            cattr.data[(vi - 1) * 4 + 2] = 0.35
            cattr.data[(vi - 1) * 4 + 4] = 0.25
        end

        cam = PerspectiveCamera(fov=π/4, aspect=1.0, near=0.1, far=100.0)
        cam.position = Vec3(0.0, 0.0, 3.0)

        scene_on = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(scene_on, Mesh(geo, MeshBasicMaterial(color=Color3(1.0, 1.0, 1.0), vertex_colors=true)))
        rt_on = RenderTarget(32, 32); render!(rt_on, scene_on, cam; shading=:smooth)
        rt_on_cached = RenderTarget(32, 32); smooth_vc_cache = RenderCache()
        render!(rt_on_cached, scene_on, cam; shading=:smooth, cache=smooth_vc_cache)
        @test maximum(abs.(rt_on.color .- rt_on_cached.color)) < 1e-12
        @test_opt_alloc 2048 render!(rt_on_cached, scene_on, cam; shading=:smooth,
                                     cache=smooth_vc_cache)
        @test rt_on.color[16, 16, 1] ≈ 0.0 atol=1e-6
        @test rt_on.color[16, 16, 2] ≈ 0.35 atol=1e-6
        @test rt_on.color[16, 16, 3] ≈ 0.0 atol=1e-6

        scene_off = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(scene_off, Mesh(geo, MeshBasicMaterial(color=Color3(1.0, 1.0, 1.0))))
        rt_off = RenderTarget(32, 32); render!(rt_off, scene_off, cam; shading=:smooth)
        @test rt_off.color[16, 16, 1] ≈ 1.0 atol=1e-6
        @test rt_off.color[16, 16, 2] ≈ 1.0 atol=1e-6
        @test rt_off.color[16, 16, 3] ≈ 1.0 atol=1e-6

        scene_phong = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(scene_phong, AmbientLight(color=Color3(1.0, 1.0, 1.0), intensity=1.0))
        add!(scene_phong, Mesh(geo, MeshPhongMaterial(color=Color3(1.0, 1.0, 1.0),
                                                      specular=Color3(0.0, 0.0, 0.0),
                                                      shininess=0.0,
                                                      vertex_colors=true)))
        rt_phong = RenderTarget(32, 32); render!(rt_phong, scene_phong, cam; shading=:smooth)
        rt_phong_cached = RenderTarget(32, 32); smooth_vc_phong_cache = RenderCache()
        render!(rt_phong_cached, scene_phong, cam; shading=:smooth,
                cache=smooth_vc_phong_cache)
        @test maximum(abs.(rt_phong.color .- rt_phong_cached.color)) < 1e-12
        @test_opt_alloc 2048 render!(rt_phong_cached, scene_phong, cam;
                                     shading=:smooth, cache=smooth_vc_phong_cache)
        @test rt_phong.color[16, 16, 1] ≈ 0.0 atol=1e-6
        @test rt_phong.color[16, 16, 2] ≈ 0.35 atol=1e-6
        @test rt_phong.color[16, 16, 3] ≈ 0.0 atol=1e-6

        phong_map_data = fill(0.6, 4, 4, 4)
        phong_map_data[:, :, 4] .= 0.75
        phong_map = Texture(phong_map_data; filter=:nearest, colorspace=:linear)
        phong_map_mat = MeshPhongMaterial(color=Color3(0.8, 0.6, 0.4),
                                          specular=Color3(0.5, 0.4, 0.3),
                                          specular_map=phong_map,
                                          glossiness_map=phong_map,
                                          vertex_colors=true)
        phong_specular, phong_shininess =
            Diff3D._phong_mapped_terms(phong_map_mat, phong_map, phong_map,
                                       0.5, 0.5, 0.5, 0.5)
        mapped_mat = Diff3D._apply_phong_maps(phong_map_mat, phong_map, phong_map,
                                              0.5, 0.5, 0.5, 0.5)
        n = Vec3(0.0, 0.0, 1.0)
        vd = Vec3(0.0, 0.0, 1.0)
        p = Vec3(0.0, 0.0, 0.0)
        vc = Color3(0.25, 0.5, 0.75)
        phong_lights = AbstractLight[
            AmbientLight(intensity=0.35),
            DirectionalLight(intensity=0.8, position=Vec3(0.0, 0.0, 2.0)),
            RectAreaLight(width=1.5, height=1.0, intensity=0.4,
                          position=Vec3(0.0, 0.0, 2.0))
        ]
        legacy_phong = shade_face(n, vd, p, Diff3D._with_vertex_color(mapped_mat, vc),
                                  phong_lights)
        fast_phong = Diff3D._shade_phong_mapped_vertex_color(
            n, vd, p, phong_map_mat, phong_lights, nothing, phong_specular,
            Float64(phong_shininess), vc)
        @test maximum(abs, (legacy_phong.r - fast_phong.r,
                            legacy_phong.g - fast_phong.g,
                            legacy_phong.b - fast_phong.b)) < 1e-12

        scene_phong_maps = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(scene_phong_maps, AmbientLight(color=Color3(1.0, 1.0, 1.0),
                                            intensity=1.0))
        add!(scene_phong_maps, Mesh(geo, phong_map_mat))
        rt_phong_maps = RenderTarget(32, 32)
        render!(rt_phong_maps, scene_phong_maps, cam; shading=:smooth)
        rt_phong_maps_cached = RenderTarget(32, 32)
        smooth_phong_maps_cache = RenderCache()
        render!(rt_phong_maps_cached, scene_phong_maps, cam; shading=:smooth,
                cache=smooth_phong_maps_cache)
        @test maximum(abs.(rt_phong_maps.color .- rt_phong_maps_cached.color)) < 1e-12
        @test_opt_alloc 2048 render!(rt_phong_maps_cached, scene_phong_maps, cam;
                                     shading=:smooth,
                                     cache=smooth_phong_maps_cache)

        physical_map_data = fill(0.65, 4, 4, 4)
        physical_map_data[:, :, 2] .= 0.45
        physical_map_data[:, :, 3] .= 0.35
        physical_map_data[:, :, 4] .= 0.55
        physical_map = Texture(physical_map_data; filter=:nearest,
                               colorspace=:linear)
        physical_map_mat = MeshPhysicalMaterial(
            color=Color3(0.8, 0.6, 0.4),
            roughness=0.7, metalness=0.3, clearcoat=0.4,
            clearcoat_roughness=0.5, transmission=0.25,
            thickness=0.3, attenuation_distance=2.0,
            sheen=0.2, sheen_color=Color3(0.4, 0.5, 0.6),
            sheen_roughness=0.8, iridescence=0.3,
            iridescence_thickness=450.0, specular_intensity=0.7,
            specular_color=Color3(0.5, 0.6, 0.7), anisotropy=0.2,
            roughness_map=physical_map, metalness_map=physical_map,
            clearcoat_map=physical_map, clearcoat_roughness_map=physical_map,
            transmission_map=physical_map, thickness_map=physical_map,
            sheen_color_map=physical_map, sheen_roughness_map=physical_map,
            iridescence_map=physical_map,
            iridescence_thickness_map=physical_map,
            specular_intensity_map=physical_map,
            specular_color_map=physical_map, anisotropy_map=physical_map,
            vertex_colors=true)
        physical_terms = Diff3D._physical_mapped_terms(
            physical_map_mat, physical_map, physical_map, 0.5, 0.5, 0.5, 0.5)
        physical_mapped_mat = Diff3D._apply_pbr_maps(
            physical_map_mat, physical_map, physical_map, 0.5, 0.5, 0.5, 0.5)
        legacy_physical = shade_face(n, vd, p,
                                     Diff3D._with_vertex_color(physical_mapped_mat, vc),
                                     phong_lights)
        fast_physical = Diff3D._shade_physical_mapped_vertex_color(
            n, vd, p, physical_map_mat, phong_lights, nothing, physical_terms, vc)
        @test maximum(abs, (legacy_physical.r - fast_physical.r,
                            legacy_physical.g - fast_physical.g,
                            legacy_physical.b - fast_physical.b)) < 1e-12

        scene_physical_maps = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(scene_physical_maps, AmbientLight(color=Color3(1.0, 1.0, 1.0),
                                               intensity=1.0))
        add!(scene_physical_maps, Mesh(geo, physical_map_mat))
        rt_physical_maps = RenderTarget(32, 32)
        render!(rt_physical_maps, scene_physical_maps, cam; shading=:smooth)
        rt_physical_maps_cached = RenderTarget(32, 32)
        smooth_physical_maps_cache = RenderCache()
        render!(rt_physical_maps_cached, scene_physical_maps, cam;
                shading=:smooth, cache=smooth_physical_maps_cache)
        @test maximum(abs.(rt_physical_maps.color .- rt_physical_maps_cached.color)) < 1e-12
        @test_opt_alloc 2048 render!(rt_physical_maps_cached,
                                     scene_physical_maps, cam;
                                     shading=:smooth,
                                     cache=smooth_physical_maps_cache)

        spec_geo = PlaneGeometry(width=2.0, height=2.0)
        set_attribute!(spec_geo, :color, fill(0.0, 3 * spec_geo.n_vertices), 3)
        spec_scene = Scene(background=Color3(0.0, 0.0, 0.0))
        add!(spec_scene, AmbientLight(color=Color3(1.0, 1.0, 1.0), intensity=0.0))
        add!(spec_scene, DirectionalLight(color=Color3(1.0, 1.0, 1.0), intensity=8.0,
                                          position=Vec3(0.0, 0.0, 3.0)))
        add!(spec_scene, Mesh(spec_geo,
                              MeshStandardMaterial(color=Color3(1.0, 1.0, 1.0),
                                                   roughness=0.12, metalness=0.0,
                                                   vertex_colors=true)))
        rt_spec = RenderTarget(32, 32)
        render!(rt_spec, spec_scene, cam; shading=:smooth)
        @test rt_spec.color[16, 16, 1] > 0.02
    end

    @testset "Near-plane clipping — geometry fully behind camera is dropped" begin
        scene = Scene(background=Color3(0.0, 0.0, 0.0))
        box = Mesh(BoxGeometry(width=1.0, height=1.0, depth=1.0),
                   MeshBasicMaterial(color=Color3(1.0, 1.0, 1.0)))
        box.position = Vec3(0.0, 0.0, 10.0)   # behind a camera at z=3 looking -z
        add!(scene, box)
