        @test all(<(0.01), rt.color)     # nothing rendered, all background
    end

    @testset "No NaN/Inf in geometry data" begin
        for (name, geo) in [
            ("Box", BoxGeometry()),
            ("Sphere", SphereGeometry()),
            ("Plane", PlaneGeometry()),
            ("Cylinder", CylinderGeometry()),
            ("Cone", ConeGeometry()),
            ("Torus", TorusGeometry()),
            ("TorusKnot", TorusKnotGeometry()),
            ("Ring", RingGeometry()),
            ("Circle", CircleGeometry()),
