            asset = load_gltf_asset(path)
            @test asset.animations[1].tracks[1] isa CubicSplineMorphWeightsKeyframeTrack
            mesh = get_children(get_children(asset.scene)[1])[1]
            mixer_set_time!(AnimationMixer(asset.animations[1]), 0.5)
